<?php $recent = new WP_Query( array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => absint( get_theme_mod( 'kimpu_blog_count', 3 ) ), 'ignore_sticky_posts' => true, 'no_found_rows' => true ) ); ?><section class="section section-muted <?php echo esc_attr( kimpu_homepage_section_classes( 'latest' ) ); ?>" id="latest"><div class="container"><?php kimpu_homepage_section_header( 'latest' ); ?><?php if ( $recent->have_posts() ) : ?><div class="post-grid homepage-blog-grid homepage-columns-<?php echo esc_attr( absint( get_theme_mod( 'kimpu_blog_columns', 3 ) ) ); ?>"><?php while ( $recent->have_posts() ) : $recent->the_post(); ?><article <?php post_class( 'post-card' ); ?>><?php if ( has_post_thumbnail() ) : ?><a class="post-thumb" href="<?php the_permalink(); ?>"><?php the_post_thumbnail( 'medium_large' ); ?></a><?php endif; ?><div class="post-content"><?php if ( get_theme_mod( 'kimpu_blog_show_category', true ) ) : ?><p class="post-meta"><?php echo wp_kses_post( get_the_category_list( ', ' ) ); ?></p><?php endif; ?><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><?php if ( get_theme_mod( 'kimpu_blog_show_excerpt', true ) ) : ?><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 20 ) ); ?></p><?php endif; ?><p class="post-meta"><?php if ( get_theme_mod( 'kimpu_blog_show_date', true ) ) { echo esc_html( get_the_date() ); } ?><?php if ( get_theme_mod( 'kimpu_blog_show_author', true ) ) { echo ' · ' . esc_html( get_the_author() ); } ?></p><a class="text-link" href="<?php the_permalink(); ?>"><?php esc_html_e( 'Read article', 'kimpu-multipurpose' ); ?> →</a></div></article><?php endwhile; ?></div><?php wp_reset_postdata(); ?><p class="section-action"><a class="button button-outline" href="<?php echo esc_url( get_permalink( get_option( 'page_for_posts' ) ) ?: home_url( '/' ) ); ?>"><?php esc_html_e( 'View all articles', 'kimpu-multipurpose' ); ?></a></p><?php else : ?><p class="empty-state"><?php esc_html_e( 'Publish your first post to show articles here.', 'kimpu-multipurpose' ); ?></p><?php endif; ?></div></section>
